import { test, expect } from '@playwright/test';

test.describe('Record Created and Modified Dates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display created and modified dates on a record', async ({ page }) => {
    // Intercept the API call to get the record data
    await page.route('**/api/records/123', (route) => {
      route.continue();
    });

    // Click on the record to open details
    const recordItem = page.getByRole('button', { name: /record 123/i });
    await recordItem.click();

    // Wait for the record details to load
    await page.waitForLoadState('networkidle');

    // Verify the record title is visible
    const recordTitle = page.getByRole('heading', { name: /record 123/i });
    await expect(recordTitle).toBeVisible();

    // Verify the created date is displayed
    const createdDateLabel = page.getByText(/created on/i);
    await expect(createdDateLabel).toBeVisible();

    const createdDateValue = page.getByText(/\d{2}\/\d{2}\/\d{4,4d}/);
    await expect(createdDateValue).toBeVisible();

    // Verify the last modified date is displayed
    const modifiedDateLabel = page.getByText(/last modified on/i);
    await expect(modifiedDateLabel).toBeVisible();

    const modifiedDateValue = page.getByText(/\d{2}\/\d{2}\/\d{4d}/);
    await expect(modifiedDateValue).toBeVisible();

    // Verify both dates are present and not empty
    await expect(createdDateValue).not.toHaveText('');
    await expect(modifiedDateValue).not.toHaveText('');
  });

  test('should handle missing modified date gracefully', async ({ page }) => {
    // Intercept the API call and return a record without a modified date
    await page.route('**/api/records/456', (route) => {
      route.abort('failed');
    });

    // Mock the successful response with only created date
    await page.route('**/api/records/456', (route) => {
      route.continue();
    });

    // Click on the record to open details
    const recordItem = page.getByRole('button', { name: /record 456/i });
    await recordItem.click();

    // Wait for the record details to load
    await page.waitForLoadState('networkidle');

    // Verify the record title is visible
    const recordTitle = page.getByRole('heading', { name: /record 456/i });
    await expect(recordTitle).toBeVisible();

    // Verify the created date is displayed
    const createdDateLabel = page.getByText(/created on/i);
    await expect(createdDateLabel).toBeVisible();

    const createdDateValue = page.getByText(/\d{2}\/\d{2}\/\d{4d}/);
    await expect(createdDateValue).toBeVisible();

    // Verify the modified date label is not present
    const modifiedDateLabel = page.getByText(/last modified on/i);
    await expect(modifiedDateLabel).not.toBeVisible();

    // Verify a fallback message is displayed when modified date is missing
    const fallbackMessage = page.getByText(/no modification date available/i);
    await expect(fallbackMessage).toBeVisible();
  });
});
